export function useTranslation(lang: LangCode) {
  const translations = T[lang] || T.it;
  const t = (key: string): string => translations[key] || T.en[key] || key;
  const isRTL = RTL_LANGS.has(lang);
  return { t, isRTL };
}

export default T;
